// Compute value picks: matches where consensus implied probability
// for the underdog is >= 15 percentage points below the Elo-based probability.
//
// Inputs:
//   $input.first().json -> array of matches from The Odds API
//   $('Load teams').first().json -> teams.json from data/
//
// Output: { matchday_label, candidates: [{home, away, market, bookie_odds, elo_prob, implied_prob, gap}] }

const matches = $input.first().json;
const teams = $('Load teams').first().json.teams;

const nameToCode = Object.fromEntries(
  Object.entries(teams).map(([code, t]) => [t.name.toLowerCase(), code])
);

function eloProb(home, away) {
  // Standard Elo win probability formula with 65 home advantage
  // (suppressed to 30 for World Cup neutral venues — adjust to 0 if you want pure rating).
  const advantage = 30;
  return 1 / (1 + Math.pow(10, -((home + advantage) - away) / 400));
}

function consensusOdds(bookmakers, outcomeName) {
  const odds = [];
  for (const bk of bookmakers ?? []) {
    const market = (bk.markets ?? []).find(m => m.key === 'h2h');
    const out = market?.outcomes?.find(o => o.name === outcomeName);
    if (out?.price) odds.push(out.price);
  }
  if (odds.length === 0) return null;
  return odds.reduce((a, b) => a + b, 0) / odds.length;
}

const candidates = [];
for (const m of matches) {
  const homeCode = nameToCode[m.home_team?.toLowerCase()];
  const awayCode = nameToCode[m.away_team?.toLowerCase()];
  if (!homeCode || !awayCode) continue;
  const homeElo = teams[homeCode].elo;
  const awayElo = teams[awayCode].elo;
  if (!homeElo || !awayElo) continue;

  const probHomeWin = eloProb(homeElo, awayElo);
  const probAwayWin = eloProb(awayElo, homeElo);
  // Draw probability ~ 0.25 in WC group stage; rescale.
  const drawScale = 0.75;
  const homeElorw = probHomeWin * drawScale;
  const awayElorw = probAwayWin * drawScale;

  const homeOdds = consensusOdds(m.bookmakers, m.home_team);
  const awayOdds = consensusOdds(m.bookmakers, m.away_team);

  for (const [side, code, name, prob, odds, opponent] of [
    ['home', homeCode, m.home_team, homeElorw, homeOdds, m.away_team],
    ['away', awayCode, m.away_team, awayElorw, awayOdds, m.home_team],
  ]) {
    if (!odds) continue;
    const implied = 1 / odds;
    const gap = prob - implied;
    if (gap >= 0.15 && odds >= 2.5) {
      candidates.push({
        home: side === 'home' ? name : opponent,
        away: side === 'away' ? name : opponent,
        market: `${name.toUpperCase()} to win`,
        bookie_odds: Number(odds.toFixed(2)),
        elo_prob: Number(prob.toFixed(2)),
        implied_prob: Number(implied.toFixed(2)),
        gap: Number(gap.toFixed(2))
      });
    }
  }
}

candidates.sort((a, b) => b.gap - a.gap);

const todayLabel = new Date().toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long' });

return [{
  json: {
    matchday_label: `Value board · ${todayLabel}`,
    candidates: candidates.slice(0, 5)
  }
}];
